-- Node: neuro-shock-map-targets (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"MAP Targets — Critical for Outcomes","body":"**2024 AO Spine / AANS / CNS Guideline (Kwon et al.) — Hemodynamic Targets:**\n\n| Parameter | Target | Duration |\n|-----------|--------|----------|\n| **MAP lower limit** | **75-80 mmHg** | 3-7 days |\n| **MAP upper limit** | **90-95 mmHg** | 3-7 days |\n\n**What changed:** The old 2013 AANS/CNS target was a narrow **85-90 mmHg** for 7 days. The 2024 GRADE update **broadened the range** (lower 75-80, upper 90-95) for **3-7 days** because the narrow 5-mmHg band was impractical and the supporting evidence is very-low quality (weak recommendation). Many centers default to **MAP ≥85** in practice.\n\n**Why this matters:**\n• Avoiding hypotension is the priority — even transient MAP dips in the first 72h are associated with worse neurologic recovery\n• Secondary injury from hypoperfusion is PREVENTABLE\n\n**Vasopressor choice:** The 2024 guideline made **no formal vasopressor recommendation** (evidence gap). Norepinephrine remains the common practical first-line; dopamine carries higher complication rates, especially in the elderly.\n\n**Monitoring:**\n• Arterial line for continuous MAP monitoring\n• Hourly neuro checks\n• UOP >30 mL/hr\n• Lactate trending\n\n**Duration:** augment for **3-7 days** post-injury (strongest signal in first 72h) [1][6]","citation":[1,6],"next":"neuro-shock-ancillary","calculatorLinks":[{"id":"neuro-shock-map-calc","label":"MAP Calculator"}],"summary":"MAP target 85-90 mmHg for 3-7 days — 2-3 mmHg difference correlates with neurologic recovery, use arterial line","safetyLevel":"critical"}'::jsonb
WHERE id = 'neuro-shock-map-targets' AND tree_id = 'neurogenic-shock';

