UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Bromocriptine","body":"**Dopamine agonist - restores dopaminergic transmission**\n\n**Dosing:**\n* **Initial:** 2.5 mg PO/NG q8h\n* **Escalate:** 5 mg q8h if no improvement in 24h\n* **Max:** 45 mg/day\n* **Duration:** Continue for 10 days minimum after NMS resolves\n\n**Route:** PO or NG tube\n\n**Mechanism:** D2 agonist - counteracts dopamine blockade\n\n**Cautions:**\n* Hypotension (start low)\n* Nausea/vomiting\n* Psychosis (rare at these doses)\n* **Prothrombotic:** bromocriptine increases MI/stroke/VTE risk — consider VTE prophylaxis/anticoagulation in immobilized NMS patients on bromocriptine [9]","citation":[4,9],"next":"nms-dantrolene","summary":"Bromocriptine 2.5 mg q8h, increase to 5 mg q8h. Continue 10 days after resolution."}'::jsonb
