UPDATE decision_nodes SET data = '{"type":"result","module":4,"title":"ICU Admission","body":"**ICU mandatory for:** [1][2][6]\n* Temp >40 degC\n* Severe rigidity\n* Rhabdomyolysis (CK >10,000)\n* Respiratory compromise\n* Renal failure\n* Autonomic instability\n\n**Mortality:** Historically reported at 10-20%, but contemporary cohorts are lower — ~5-10% in-hospital, with 30-day mortality near 4.7% and 1-year mortality ~15.1% in recent data. Risk rises with delayed diagnosis, severe rhabdomyolysis, and renal failure. [3][7][9]","citation":[1,2,3,6,7,9],"recommendation":"ICU admission for severe NMS.","confidence":"definitive","summary":"ICU for severe NMS. Modern mortality ~5-10% in-hospital (30-day ~4.7%), historically up to 20%."}'::jsonb
