-- Node: pericarditis-steroids (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Corticosteroid Therapy","body":"**Avoid steroids first-line — increase recurrence risk 2-4x** [1][2][3]\n\n**Note (2025 ACC):** for recurrent/refractory inflammatory-phenotype pericarditis, IL-1 inhibitors are now preferred over escalating corticosteroids — see [Refractory Pericarditis](#/node/pericarditis-refractory). [15]\n\n**Indications for steroids:**\n• Contraindication to NSAIDs (renal failure, active GI bleeding)\n• Contraindication to colchicine\n• NSAID failure after 1-2 weeks\n• Autoimmune/connective tissue disease\n• Pregnancy (aspirin + colchicine can be used, but steroids if needed)\n\n**If steroids required:**\n• Low dose: [Prednisone](#/drug/prednisone/pericarditis) 0.25-0.5 mg/kg/day (NOT high-dose)\n• Maximum ~25mg/day for most patients\n• Continue colchicine throughout\n• **Very slow taper** — key to preventing recurrence\n\n**Taper protocol:**\n• Maintain dose until symptom-free + CRP normal (usually 2-4 weeks)\n• Then decrease by 2.5-5mg every 2 weeks (if >25mg/day)\n• Below 25mg: decrease by 1.25-2.5mg every 2-4 weeks\n• Total taper duration: often 3-6 months\n\n**If flare during taper:**\n• Return to last effective dose\n• Add/optimize colchicine\n• Consider steroid-sparing agent","citation":[1,2,3],"next":"pericarditis-recurrent","treatment":{"firstLine":{"drug":"Prednisone","dose":"0.25-0.5 mg/kg/day (max ~25 mg)","route":"PO","frequency":"Daily","duration":"Until symptom-free + CRP normal, then very slow taper over 3-6 months","notes":"Only if NSAID contraindicated or failed. Continue colchicine. Low dose preferred."},"monitoring":"CRP to guide taper; blood glucose; BP; symptoms during taper — flare = return to last effective dose"},"summary":"Avoid first-line (2-4x recurrence risk); if needed: low dose 0.25-0.5 mg/kg (max 25mg); very slow taper over months; 2025 ACC: IL-1 preferred over steroids for recurrent inflammatory phenotype","safetyLevel":"warning"}'::jsonb
WHERE id = 'pericarditis-steroids' AND tree_id = 'pericarditis';

-- Node: pericarditis-recurrent (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":5,"title":"Recurrent Pericarditis","body":"**Recurrence occurs in 15-30% despite optimal therapy** [1][13]\n\n**Definitions:**\n• **Recurrent:** symptom-free interval ≥4-6 weeks between episodes\n• **Incessant:** symptoms persist >4-6 weeks OR recurrence within 6 weeks of stopping therapy\n\n**Risk factors for recurrence:**\n• Incomplete initial treatment\n• Premature NSAID taper\n• Not using colchicine\n• Steroid use (especially high-dose or rapid taper)\n• Female sex\n• Autoimmune etiology\n\n**Recurrence management ladder (2025 ACC update):**\n1. NSAIDs + colchicine (longer duration — 6 months)\n2. **IL-1 antagonists (anakinra, rilonacept, goflikicept)** — now preferred over corticosteroids as second-line for the inflammatory phenotype (2025 ACC Expert Consensus)\n3. Low-dose corticosteroids with very slow taper — if IL-1 unavailable/contraindicated or non-inflammatory phenotype\n4. Other immunosuppressants (azathioprine, IVIG)\n5. Pericardiectomy (last resort)","citation":[1,13],"options":[{"label":"First Recurrence","next":"pericarditis-recurrent-first"},{"label":"Multiple Recurrences / Steroid-Dependent","next":"pericarditis-refractory"},{"label":"Incessant Pericarditis","description":"Never achieved remission","next":"pericarditis-refractory"}],"summary":"15-30% recurrence; risk factors: no colchicine, rapid taper, steroids, female; escalation: NSAIDs → steroids → IL-1 blockers"}'::jsonb
WHERE id = 'pericarditis-recurrent' AND tree_id = 'pericarditis';

-- Node: pericarditis-refractory (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Refractory / Steroid-Dependent Pericarditis","body":"**IL-1 antagonists are now preferred over corticosteroids as second-line for the inflammatory phenotype** (2025 ACC Expert Consensus) [1][13][14][15]\n\n**Indications for IL-1 therapy:**\n• Recurrent/incessant pericarditis after failing colchicine (typically by 2nd recurrence)\n• Steroid-dependent (unable to taper below physiologic dose)\n• Contraindication to steroids\n• Inflammatory phenotype (elevated CRP, fever, pericardial enhancement on CMR)\n\n**IL-1 antagonists:**\n\n| Drug | Dose | Notes |\n|------|------|-------|\n| **Rilonacept** | 320mg SC load, then 160mg weekly | FDA-approved for recurrent pericarditis (RHAPSODY trial) |\n| **Anakinra** | 100mg SC daily | Rapid onset, injection site reactions (AIRTRIP trial) |\n| **Goflikicept** | Per protocol | Newer IL-1 trap, named in 2025 ACC consensus |\n\n**Trial evidence:** [14]\n• RHAPSODY (rilonacept): 96% reduction in recurrence vs placebo, rapid symptom relief (median 5 days)\n• AIRTRIP (anakinra): 18% vs 90% recurrence after withdrawal\n\n**Weaning once on IL-1 therapy:** sequentially wean prednisone → NSAID → colchicine (colchicine may be continued for additive benefit). Treatment duration ≥12 months, individualized to clinical/biomarker/imaging remission.\n\n**Other options:**\n• Azathioprine (steroid-sparing)\n• IVIG (limited evidence)\n• Pericardiectomy — last resort for truly refractory cases\n\n**Referral:**\n• Rheumatology and/or cardiology subspecialty involvement recommended","citation":[1,13,14,15],"next":"pericarditis-disposition","treatment":{"firstLine":{"drug":"Rilonacept","dose":"320 mg SC load, then 160 mg SC weekly","route":"SC","frequency":"Weekly after loading","duration":"Until remission, then taper","notes":"FDA-approved for recurrent pericarditis. Alternative: Anakinra 100mg SC daily."},"alternative":{"drug":"Anakinra","dose":"100 mg","route":"SC","frequency":"Daily","duration":"Until remission achieved","notes":"Faster onset but daily injection. Consider if rilonacept unavailable."},"monitoring":"CRP, symptoms, injection site reactions; rheumatology co-management recommended"},"summary":"Refractory: IL-1 antagonists preferred (rilonacept FDA-approved, anakinra); RHAPSODY showed 96% recurrence reduction"}'::jsonb
WHERE id = 'pericarditis-refractory' AND tree_id = 'pericarditis';

